INSERT INTO place_details (id, place_id, description, significance, best_time, peak_months, off_peak_months, daily_timings, rituals, reach_info, images, tags, avg_daily_footfall, festival_rush_multiplier, queue_config) VALUES
(1, 1, 'An ancient Hindu temple dedicated to Lord Shiva, situated at an altitude of 3,583 meters in the Garhwal Himalayan range.', 'One of the twelve Jyotirlingas and a vital part of the Char Dham Yatra, symbolizing spiritual liberation.', 'May to June or September to October to avoid extreme weather and monsoon risks.', '["May", "June"]', '["July", "August", "November"]', '{"open": "04:00", "close": "21:00", "aartiTimings": ["04:00", "18:30"]}', '[{"name": "Maha Abhishek", "time": "04:00", "description": "The morning ritual involving the ritual bathing of the Shiva Lingam."}, {"name": "Sandhya Aarti", "time": "18:30", "description": "Evening devotional lamp ceremony performed in praise of Lord Shiva."}]', '{"byAir": "Nearest airport is Jolly Grant Airport, Dehradun.", "byRoad": "Road connectivity up to Sonprayag/Gaurikund.", "byTrain": "Nearest railway station is Rishikesh.", "trekInfo": "16 km trek from Gaurikund, taking approximately 6-8 hours depending on physical fitness."}', '["https://upload.wikimedia.org/wikipedia/commons/4/4b/Kedarnath_Temple_1.jpg", "https://upload.wikimedia.org/wikipedia/commons/c/c5/Kedarnath_Temple_Uttarakhand.jpg", "https://images.unsplash.com/photo-1626082897645-316260840484"]', '["spiritual", "temple", "trek", "himalayas"]', 15000, 2.5, '{"avgGroupSize": 2, "throughputPerMinute": 25}'),
(2, 4, 'Kashi Vishwanath is one of the holiest Shiva temples in India and among the twelve Jyotirlingas. It receives massive daily pilgrimage traffic throughout the year.', 'One of the most sacred temples dedicated to Lord Shiva.', 'Early Morning (4 AM - 7 AM)', '["Shravan", "Mahashivratri", "Dev Deepawali"]', '["July", "August"]', '{"open": "04:00 AM", "close": "11:00 PM"}', '[{"name": "Mangala Aarti", "time": "03:00 AM"}, {"name": "Bhog Aarti", "time": "11:15 AM"}, {"name": "Sandhya Aarti", "time": "07:00 PM"}, {"name": "Shringar Aarti", "time": "09:00 PM"}]', '{"byAir": "Lal Bahadur Shastri International Airport (26 km). Taxis and buses available to temple corridor.", "byRail": "Varanasi Junction and Manduadih stations connected to all major Indian cities.", "byRoad": "Accessible via NH-19. Electric shuttle and walking corridor available near temple."}', '["https://upload.wikimedia.org/wikipedia/commons/3/3f/Kashi_Vishwanath.jpg"]', '["Shiva", "Jyotirlinga", "Varanasi", "Temple", "Pilgrimage"]', 150000, 4.0, '{"mode": "Hybrid Virtual Queue", "liveMonitoring": true, "communityEnabled": true}'),
(3, 5, 'Sacred cave shrine of Goddess Vaishno Devi in Trikuta mountains, 12km uphill trek from Katra base camp.', 'One of India''s most visited pilgrimage sites, fulfills wishes of devotees.', 'Summer (Mar-Jun) for pleasant weather, avoid peak Navratri.', '["March", "April", "September", "October", "November"]', '["January", "February", "July", "August"]', '{"open": "04:00", "close": "23:00"}', '[{"name": "Shringar Aarti", "time": "07:30"}, {"name": "Havan Aarti", "time": "12:00"}, {"name": "Sandhya Aarti", "time": "19:00"}]', '{"byAir": "Jammu Airport (45km), helicopters from Katra helipad", "byRail": "Udhampur or Katra Railway Station", "byRoad": "Jammu-Katra highway, taxis/buses from Jammu (50km)"}', '["https://upload.wikimedia.org/wikipedia/commons/7/70/Vaishno_Devi_Bhavan.jpg"]', '["pilgrimage", "temple", "trek", "navratri", "shrine"]', 26000, 4.0, '{"mode": "RFID_Parchi", "liveMonitoring": true, "communityEnabled": true}');
